// New rules, part 2: typography, icons, layout, input, content, flow, accessibility. Same conventions as text.mjs.
import { ref } from '../lib/common.mjs'
import { r } from './text.mjs'

export const RULES_UI = [
  // ------------------------------------------------------------------ typography
  r('R-TYPE-002', 'typography', 'must',
    ['ارتفاع السطر يُقاس بنص مشكول', 'Line height is measured with vocalised text'],
    ['حدّد ارتفاع السطر لكل خط عربي بعد قياس سطر مشكول تشكيلًا كاملًا فيه حروف صاعدة وهابطة. الحاويات ذات السطر الواحد لا تقص العلامات (لا overflow: hidden على ارتفاع يساوي ارتفاع الخط).', 'Set the line height of each Arabic typeface after measuring a fully vocalised line with ascending and descending letters. Single-line containers must not clip marks (no overflow: hidden on a height equal to the font\'s).'],
    ['الحروف العربية تصعد وتهبط أكثر من اللاتينية، والتشكيل يتراكم فوق الشدّة وتحت الحرف. ارتفاع سطر مناسب للاتينية يقص الضمة والكسرة أو يُدخل سطرين في بعضهما.', 'Arabic letters rise and descend further than Latin ones, and marks stack above a shadda and below the letter. A line height that suits Latin clips marks or makes two lines collide.'],
    { appliesTo: ['tokens', 'text', 'button', 'input', 'table'], checks: ['For text-stress TS-052 at every type token, the ink bounding box of each line lies within its line box.', 'Two consecutive lines of TS-052 have no overlapping ink.', 'In buttons, inputs, chips and table cells, the ink of TS-050 is not clipped by the element\'s box.', 'Line-height tokens for Arabic are unitless and recorded per font with the measured ink extents.'], references: [ref('alreq', '7.4 Baselines, line height, etc.; 4.2.8 Positioning diacritics'), ref('wcag', '1.4.12 Text Spacing')], fixtures: ['text-stress'], related: ['R-TYPE-001', 'R-A11Y-006'] }),
  r('R-TYPE-003', 'typography', 'must',
    ['القص عند نهاية القراءة وبحدود العناقيد', 'Truncate at the reading end, on grapheme boundaries'],
    ['النص المقصوص يُقطع عند نهايته في اتجاه قراءته وتظهر علامة الحذف هناك (يسار السطر في نص عربي). القص البرمجي يتم عند حدود عنقود كتابي ولا يفصل حرفًا عن تشكيله ولا يشطر عزلًا اتجاهيًا. والنص الكامل متاح دائمًا.', 'Truncated text is cut at its end in reading direction and the ellipsis appears there (the left of the line for Arabic). Programmatic truncation cuts on a grapheme-cluster boundary, never separates a letter from its marks and never splits a directional isolate. The full text is always available.'],
    ['text-overflow يقص عند طرف نهاية السطر بحسب اتجاه الحاوية؛ فإن كان اتجاه الحاوية غير اتجاه النص ظهر الحذف عند بداية النص. والقص بعدد وحدات UTF-16 يشطر الإيموجي والحرف عن علاماته.', 'text-overflow clips at the line\'s end edge according to the container\'s direction; if that differs from the text\'s direction the ellipsis appears at the start of the text. Cutting by UTF-16 units splits emoji and separates letters from their marks.'],
    { appliesTo: ['truncate', 'text', 'table', 'badge'], checks: ['A truncated Arabic line in an RTL container has its ellipsis at the left edge and its first word at the right edge.', 'truncate(text, n) for every text-stress and names case returns a prefix whose grapheme count is at most n and which ends on a cluster boundary.', 'A truncated element exposes the full text (title, tooltip or expansion) and its accessible name is the full text.', 'Truncating mixed-direction strings does not leave an unbalanced isolate.'], references: [ref('cssOverflow', '5.1 text-overflow'), ref('alreq', '5.2 Grapheme/word segmentation & selection')], fixtures: ['text-stress', 'names', 'mixed-direction'], related: ['R-BIDI-005'] }),
  r('R-TYPE-004', 'typography', 'must',
    ['لا تحويل لحالة الأحرف ولا مائل مصطنع للعربية', 'No case transforms and no synthetic italics for Arabic'],
    ['لا تعتمد على الأحرف الكبيرة للتمييز: العربية بلا حالة أحرف، وtext-transform: uppercase يغيّر اللاتيني وحده داخل النص المختلط. لا تستخدم المائل ولا الغامق المصطنعين مع العربية؛ التمييز بالوزن الحقيقي أو اللون أو الحجم.', 'Do not rely on capitals for emphasis: Arabic has no case, and text-transform: uppercase changes only the Latin inside mixed text. Do not use synthetic italic or synthetic bold with Arabic; emphasise with a real weight, colour or size.'],
    ['تسمية بأحرف كبيرة صغيرة الحجم تصير في العربية نصًا صغيرًا بلا تمييز. والإمالة الآلية تشوّه الحروف المتصلة، ولا تقليد للمائل في الكتابة العربية.', 'A small all-caps label becomes, in Arabic, small text with no emphasis. Automatic slanting distorts joined letters, and Arabic writing has no italic tradition.'],
    { appliesTo: ['tokens', 'text', 'button', 'badge'], checks: ['No style applied to elements with Arabic text declares text-transform other than none.', 'font-synthesis is none (or weight and style are not synthesised) for Arabic font families.', 'Every weight used with an Arabic family exists as a real face in the font record.', 'A style that pairs uppercase with a small size has an Arabic variant with a larger size or heavier weight.'], references: [ref('cssText3', '2.1 text-transform'), ref('cssFonts', '6.3 font-synthesis'), ref('appleRtl', 'Controls: balancing Latin capitals with RTL scripts'), ref('alreq', '4.1 Fonts & font styles')], fixtures: ['names'], related: ['R-TYPE-008'] }),
  r('R-TYPE-005', 'typography', 'must',
    ['ترتيب الخطوط: خط عربي مقصود قبل خط النظام', 'Font stack: an intended Arabic face before the system fallback'],
    ['كل مجموعة خطوط تُسمّي خطًا عربيًا محددًا تغطيته للحروف والتشكيل معروفة، قبل الخطوط العامة. إذا اقترن بخط لاتيني فليكن اللاتيني محدودًا بـ unicode-range أو تاليًا له، مع مطابقة المقاسات البصرية بين الخطين.', 'Every font stack names a specific Arabic typeface whose coverage of letters and marks is known, ahead of generic families. If it is paired with a Latin face, the Latin one is limited by unicode-range or listed after it, with the two optically matched in size.'],
    ['حين لا يغطي الخط الأول العربية يختار المتصفح بديلًا يختلف من جهاز إلى آخر في الوزن والارتفاع، وقد يتغير الخط وسط الكلمة عند حرف أو علامة غير مغطاة فينقطع الاتصال.', 'When the first font lacks Arabic the browser picks a fallback that differs between devices in weight and height, and the font may change in mid-word at an uncovered letter or mark, breaking the join.'],
    { appliesTo: ['tokens', 'fonts'], checks: ['The first family in every stack that renders Arabic covers U+0621–U+064A, U+064B–U+0652, U+0660–U+0669 and U+066A–U+066C (checked against the font record).', 'Rendering text-stress TS-050 uses one font for all glyphs of each word.', 'The Arabic and Latin faces of a pair differ in x-height-equivalent by no more than the tolerance recorded in the font data, or size-adjust is set.'], references: [ref('cssFonts', '5.2 font-family; 4.5 unicode-range; 6.x size-adjust'), ref('alreq', '4.1 Fonts & font styles')], fixtures: ['text-stress'], related: ['R-TYPE-002'] }),
  r('R-TYPE-006', 'typography', 'should',
    ['لا ضبط كامل للسطور في الواجهة', 'No full justification in interface text'],
    ['نص الواجهة يُحاذى إلى البداية. إن لزم الضبط الكامل في نص طويل فبتمديد المسافات بين الكلمات أو بالكشيدة التي يدعمها الخط، لا بالمباعدة بين الحروف، ولا تُدرج محارف التطويل (U+0640) في البيانات لتحقيقه.', 'Interface text is start-aligned. If long text must be justified, do it by stretching inter-word spaces or with kashida the font supports, never by letter-spacing, and never by inserting tatweel characters (U+0640) into the data.'],
    ['الضبط في العربية يتم تقليديًا بإطالة الوصلات، وأغلب محركات العرض لا تنفذه فتوسّع المسافات حتى تتشكل أنهار بيضاء في الأعمدة الضيقة.', 'Arabic justification is traditionally done by elongating connections; most engines do not implement it and widen spaces until rivers form in narrow columns.'],
    { appliesTo: ['text', 'tokens'], checks: ['No component style declares text-align: justify.', 'Where justify is used, text-justify is inter-word or auto and letter-spacing is 0.', 'No message string contains U+0640 except where the tatweel is the content.'], references: [ref('alreq', '7.2 Text alignment & justification; 7.2.5 Kashida; 7.2.6 Tatweel'), ref('cssText3', '7.3 text-justify')], fixtures: ['text-stress'], related: ['R-TYPE-001'] }),
  r('R-TYPE-007', 'typography', 'must',
    ['الكلمة الطويلة تنكسر ولا تُخرج التخطيط عن حدوده', 'A long word wraps instead of breaking the layout'],
    ['كل حاوية نص تتحمل سلسلة بلا مسافات (رابط، رقم، كلمة ممدودة بالكشيدة) دون تمرير أفقي ولا تمدد للعمود: overflow-wrap: anywhere أو قص معلن. لا تُستخدم الواصلة لقطع الكلمات العربية.', 'Every text container tolerates a string with no spaces (a URL, a number, a word stretched with tatweel) without horizontal scrolling or column growth: overflow-wrap: anywhere, or declared truncation. Hyphens are not used to break Arabic words.'],
    ['العربية لا تُقطع كلماتها بواصلة. وعند الكسر الاضطراري يعيد المحرك تشكيل الحرفين على جانبي القطع، وهو مقبول للسلاسل غير اللغوية.', 'Arabic words are not hyphenated. On an emergency break the engine reshapes the letters on each side, which is acceptable for non-linguistic strings.'],
    { appliesTo: ['text', 'table', 'toast', 'dialog'], checks: ['With text-stress TS-001…TS-005 as content, no component makes the page scroll horizontally at 320 CSS px width.', 'hyphens is manual or none for Arabic text.', 'A table column with TS-002 keeps its declared width.'], references: [ref('alreq', '7.1 Line breaking & hyphenation'), ref('cssText3', '5.5 overflow-wrap; 6 hyphens'), ref('wcag', '1.4.10 Reflow')], fixtures: ['text-stress'], related: ['R-TYPE-003'] }),
  r('R-TYPE-008', 'typography', 'should',
    ['وازن حجم العربية بجوار اللاتينية', 'Balance the size of Arabic beside Latin'],
    ['في السطر الواحد يُضبط حجم الخط العربي أو اللاتيني حتى يتقارب الارتفاع البصري للحروف، ويُتحقق من أصغر حجم مستعمل بنص عربي فيه نقاط وتشكيل.', 'On one line, the Arabic or the Latin size is adjusted until the optical height of the letters is close, and the smallest size in use is verified with Arabic text that has dots and marks.'],
    ['بالحجم الاسمي نفسه تبدو العربية أصغر من اللاتينية خاصة بجوار الأحرف الكبيرة، وتتلاصق النقاط في الأحجام الصغيرة.', 'At the same nominal size Arabic looks smaller than Latin, especially beside capitals, and dots merge at small sizes.'],
    { appliesTo: ['tokens', 'fonts'], checks: ['The type scale records, per font pair, the ratio applied to Arabic (or Latin) and the measured heights that justify it.', 'The smallest text token renders ب ت ث ي with distinguishable dot counts at 1x device pixel ratio.'], references: [ref('appleRtl', 'Controls: visually balance adjacent Latin and RTL scripts'), ref('alreq', '4.1 Fonts & font styles')], related: ['R-TYPE-005'] }),
  r('R-TYPE-009', 'typography', 'must',
    ['تعديل المستخدم لتباعد النص لا يُفقد محتوى', 'User text-spacing overrides lose no content'],
    ['حين يفرض المستخدم ارتفاع سطر 1.5 وتباعد فقرات وكلمات أكبر، لا يُقص نص ولا يتراكب. لا تحدد ارتفاعات ثابتة لحاويات النص. أما تباعد الحروف المفروض فيفصل الحروف العربية بحكم الخط، وليس للواجهة أن تمنعه ولا أن تبني عليه.', 'When a person imposes line height 1.5 and larger paragraph and word spacing, no text is clipped or overlapped. Do not give text containers fixed heights. Imposed letter-spacing does separate Arabic letters, by the nature of the script; the interface neither blocks it nor depends on it.'],
    ['معيار 1.4.12 يطلب ألا يضيع محتوى عند تعديل التباعد. قيمه وُضعت للكتابات غير المتصلة؛ في العربية يبقى الالتزام بعدم القص، ولا يُطلب أن يبقى الشكل سليمًا تحت تباعد الحروف.', 'Criterion 1.4.12 requires that no content is lost when spacing is overridden. Its values were set for non-joining scripts; for Arabic the duty not to clip remains, and intact shaping under letter-spacing is not required.'],
    { appliesTo: ['text', 'button', 'input', 'table', 'tokens'], checks: ['With line-height 1.5, paragraph spacing 2em and word-spacing 0.16em forced on all elements, no element\'s scroll size exceeds its client size because of text.', 'No text container has a fixed block size in px.', 'The component styles themselves set no letter-spacing on Arabic text (R-TYPE-001).'], references: [ref('wcag', '1.4.12 Text Spacing'), ref('alreq', '7.3 Text spacing; 4.3 Cursive text'), ref('cssText3', '8.2 letter-spacing (cursive scripts)')], fixtures: ['text-stress'], related: ['R-TYPE-001', 'R-TYPE-002'] }),
  r('R-TYPE-010', 'typography', 'should',
    ['لا تنسّق حرفًا من كلمة بعنصر يقطع الاتصال', 'Do not style one letter of a word in a way that breaks joining'],
    ['تلوين أو تظليل جزء من كلمة عربية (نتيجة بحث، حرف اختصار) يجب أن يحافظ على أشكال الاتصال. لا تضع حشوًا أو هامشًا أو حدًّا أو خطًّا مختلفًا على العنصر الداخلي، ولا تستعمل أول حرف مكبّرًا أو مسطّرًا للدلالة على مفتاح اختصار.', 'Colouring or highlighting part of an Arabic word (a search hit, an access key) must preserve joining forms. Put no padding, margin, border or different font on the inner element, and do not enlarge or underline a first letter to show an access key.'],
    ['تغيير الخط أو إضافة مسافة بين عنصرين مضمَّنين يوقف التشكيل عند الحد فيظهر الحرف بشكله المنفصل. والتسطير يختلط بنقاط الحروف السفلية.', 'A font change or added space between two inline elements stops shaping at the boundary, so the letter appears in its isolated form. An underline collides with the dots below letters.'],
    { appliesTo: ['highlight', 'menu', 'text'], checks: ['The highlight element has zero inline padding, margin and border and inherits font-family, font-size and font-weight.', 'Underlines on Arabic text use text-decoration-skip-ink: auto or are replaced by another indicator.', 'Access keys are shown as a separate hint, not as a styled letter inside the label.'], references: [ref('alreq', '4.3.7.4 Styling individual letters; 4.3.7.3 Text border'), ref('cssText3', 'letter-spacing and cursive scripts')], fixtures: ['search-harvested'], related: ['R-SRCH-004'] }),

  // ------------------------------------------------------------------ icons
  r('R-ICON-001', 'icons', 'must',
    ['اعكس ما يدل على الاتجاه والتقدم فقط', 'Mirror only what denotes direction and progress'],
    ['تُعكس الأيقونات التي تمثل اتجاه القراءة أو التقدم أو التراجع أو ترتيب عناصر: الرجوع والتالي والأسهم التنقلية، المسافة البادئة، القوائم، الإرسال، التراجع والإعادة، مؤشر التوسيع. ولا تُعكس: علامة الصح، الساعة وما يدور باتجاه عقاربها، التشغيل الإعلامي، الشعارات، الأيقونات التي تحمل حروفًا أو أرقامًا، والأشياء المادية التي لا اتجاه لها.', 'Mirror icons that represent reading direction, forward or backward movement, or the order of items: back, next and navigation arrows, indent, lists, send, undo and redo, the disclosure chevron. Do not mirror: the check mark, the clock and anything that turns clockwise, media playback, logos, icons that contain letters or digits, and physical objects with no direction.'],
    ['ما يتحرك مع اتجاه القراءة يُفهم تقدمًا. أما الوقت فيدور في اتجاه واحد في كل مكان، وشريط التشغيل يمثل اتجاه الشريط لا القراءة، وعكس الشعار يشوهه.', 'What moves with the reading direction is understood as forward. Time, however, turns one way everywhere, a playback control represents the tape rather than reading, and a flipped logo is a damaged logo.'],
    { appliesTo: ['icon', 'icon-registry'], checks: ['Every icon record has mirror: auto | never and, for auto, the reason category (navigation, text-direction, order, motion).', 'Icons whose name matches check, clock, play, pause, refresh-clockwise, logo or contains a glyph are never.', 'In dir=rtl the back icon points to the right and the next icon to the left.', 'An icon that contains a slash, badge or question mark is reviewed: the record states whether the component is flipped.'], references: [ref('appleRtl', 'Interface icons; Controls'), ref('materialBidi', 'Mirroring icons; when not to mirror')], related: ['R-BIDI-002', 'R-ICON-003'] }),
  r('R-ICON-002', 'icons', 'must',
    ['الانعكاس يُطبَّق من السجل عند العرض وموضع الأيقونة منطقي', 'Mirroring is applied from the registry at render time; icon placement is logical'],
    ['مكوّن الأيقونة يقرأ سلوك الانعكاس من السجل ويطبقه بحسب اتجاه أقرب سياق، دون نسخة ثانية من الرسم ودون قرار في موضع الاستخدام. وموضع الأيقونة بالنسبة إلى النص يُعبَّر عنه بالبداية والنهاية.', 'The icon component reads the mirroring behaviour from the registry and applies it according to the direction of the nearest scope, with no second copy of the artwork and no decision at the call site. The icon\'s position relative to text is expressed as start or end.'],
    ['قرار الانعكاس عند كل استخدام يُنسى أو يتناقض. والموضع الفيزيائي (يسار، يمين) يضع أيقونة البداية في نهاية الزر عند قلب الاتجاه.', 'A mirroring decision made at each call site is forgotten or contradicted. Physical placement (left, right) puts the leading icon at the trailing end when the direction flips.'],
    { appliesTo: ['icon', 'button', 'input'], checks: ['The icon component has no flip or mirror prop; its transform is derived from the registry and the inherited direction.', 'Component props that place an icon are named start/end (or leading/trailing), never left/right.', 'An icon inside an element with dir="ltr" nested in an RTL page is not mirrored.'], references: [ref('cssLogical', '1 Introduction; flow-relative values'), ref('appleRtl', 'Interface icons')], related: ['R-ICON-001', 'R-LAYOUT-001'] }),
  r('R-ICON-003', 'icons', 'must',
    ['السهم الذي يشير إلى مكان حقيقي لا يُعكس', 'An arrow that points to a real place is not mirrored'],
    ['فرّق بين اتجاه السرد (التالي، السابق) والاتجاه الفيزيائي (محاذاة إلى اليمين، انتقل يمينًا على الخريطة، تدوير). الأول يتبع اتجاه الواجهة والثاني ثابت. وأسهم الفرز والارتفاع والانخفاض الرأسية لا تتأثر.', 'Distinguish narrative direction (next, previous) from physical direction (align right, pan right on a map, rotate). The first follows the interface direction; the second is fixed. Vertical arrows for sorting, increase and decrease are unaffected.'],
    ['زر «محاذاة إلى اليمين» يجب أن يحاذي إلى اليمين في كل لغة.', 'An "align right" button must align to the right in every language.'],
    { appliesTo: ['icon', 'icon-registry', 'toolbar'], checks: ['Icons in the registry categories physical-direction and vertical are never mirrored.', 'The accessible name of a mirrored navigation icon is the action («التالي»), not the direction of the drawing.', 'Text-alignment controls keep their artwork and their effect in both directions.'], references: [ref('appleRtl', 'Controls: preserve the direction of a control that refers to an actual direction'), ref('materialBidi')], related: ['R-ICON-001', 'R-A11Y-001'] }),

  // ------------------------------------------------------------------ layout
  r('R-LAYOUT-001', 'layout', 'must',
    ['خصائص منطقية فقط', 'Logical properties only'],
    ['الأنماط تستخدم الخصائص والقيم المنطقية (inline-start/end، margin-inline، padding-inline، inset-inline، border-start-*-radius، text-align: start، float: inline-start) ولا تذكر left وright إلا في ما هو فيزيائي بطبيعته.', 'Styles use logical properties and values (inline-start/end, margin-inline, padding-inline, inset-inline, border-start-*-radius, text-align: start, float: inline-start) and mention left and right only for what is physical by nature.'],
    ['ورقة أنماط واحدة تخدم الاتجاهين دون نسخة RTL تُنسى عند التعديل، وتعمل للعناصر المتداخلة المختلفة الاتجاه.', 'One stylesheet serves both directions with no RTL copy to forget when editing, and it works for nested elements of a different direction.'],
    { appliesTo: ['recipes', 'tokens', 'layout'], checks: ['The built CSS contains no margin-left/right, padding-left/right, left:, right:, border-left/right, text-align: left/right, float: left/right or clear: left/right outside an allowlist with a stated reason.', 'No [dir=rtl] selector overrides a physical property that a logical one could express.', 'Each component\'s RTL screenshot equals the horizontal mirror of its LTR screenshot, except for regions listed as not mirrored.'], references: [ref('cssLogical', '4 Flow-relative box model properties; 2 Flow-relative values'), ref('cssWritingModes', '6 Abstract box terminology')], related: ['R-LAYOUT-002', 'R-ICON-002'] }),
  r('R-LAYOUT-002', 'layout', 'must',
    ['المكوّن لا يأخذ اتجاهًا ولا يسمّي جهة فيزيائية', 'A component takes no direction and names no physical side'],
    ['الاتجاه يُورَث من السياق (سمة dir على الجذر أو على نطاق). لا يوجد خاصية dir على المكونات، وأسماء الخصائص والقيم العامة تستخدم start وend.', 'Direction is inherited from context (the dir attribute on the root or on a scope). Components have no dir prop, and public prop names and values use start and end.'],
    ['خاصية اتجاه على كل مكوّن تسمح بتناقض بين المكوّن وما حوله، وتُضاعف مساحة الاختبار.', 'A direction prop on every component allows a component to contradict its surroundings and doubles the test surface.'],
    { appliesTo: ['component-api'], checks: ['No public component prop is named dir, rtl, left or right, and no prop value is "left" or "right" (except in components whose subject is physical, such as a text-alignment control).', 'Engines read direction from one context value, and every keyboard and placement test runs in both directions.'], references: [ref('structuralBidi'), ref('cssLogical')], related: ['R-BIDI-013', 'R-LAYOUT-001'] }),
  r('R-LAYOUT-003', 'layout', 'must',
    ['التمرير الأفقي يبدأ من بداية الاتجاه', 'Horizontal scrolling starts at the direction\'s start'],
    ['الحاويات المتمررة أفقيًا (جداول، ألسنة، شرائح) تبدأ عند حافة البداية (اليمين في RTL)، وحسابات الموضع تعتمد على الإزاحة المنطقية لا على scrollLeft الخام. وشريط التمرير الرأسي يُترك في الموضع الذي يختاره المتصفح.', 'Horizontally scrolling containers (tables, tabs, carousels) start at the start edge (the right in RTL), and position arithmetic uses a logical offset rather than raw scrollLeft. The vertical scrollbar is left where the browser puts it.'],
    ['في RTL تكون scrollLeft صفرًا عند اليمين وسالبة باتجاه اليسار. الكود الذي يفترض قيمًا موجبة يجعل أزرار التمرير تعمل عكسًا وظلال الحواف تظهر في الجهة الخطأ.', 'In RTL scrollLeft is zero at the right and negative toward the left. Code that assumes positive values makes scroll buttons work backwards and edge shadows appear on the wrong side.'],
    { appliesTo: ['table', 'tabs', 'carousel', 'virtual-list'], checks: ['On first render in RTL the first item of a scroller is adjacent to the right edge.', 'Pressing the "scroll toward end" control in RTL decreases scrollLeft.', 'The start-edge shadow is on the right in RTL when scrolled away from the start.', 'Pinned columns use inline-start/inline-end offsets (table model: start and end, never left and right).'], references: [ref('cssWritingModes', '2.1 direction'), ref('cssOverflow', '2 Scrolling and clipping; scroll origin'), ref('cssLogical')], fixtures: ['table-harvested'], related: ['R-LAYOUT-001'] }),
  r('R-LAYOUT-004', 'layout', 'must',
    ['ما يعبّر عن تقدم يتبع الاتجاه', 'Whatever shows progress follows the direction'],
    ['شريط التقدم والمنزلق والتقييم والخطوات والتصفّح بين الصفحات والشرائح تمتلئ وتتقدم من البداية إلى النهاية: من اليمين إلى اليسار في RTL. ترتيب الأرقام المصاحبة ينعكس، والأرقام نفسها لا تنعكس.', 'Progress bars, sliders, ratings, steppers, pagination and carousels fill and advance from start to end: right to left in RTL. The order of accompanying numbers is reversed; the numbers themselves never are.'],
    ['القارئ يرى التقدم في اتجاه قراءته. شريط يمتلئ من اليسار في واجهة عربية يُقرأ كأنه يتناقص.', 'A reader sees progress in the reading direction. A bar filling from the left in an Arabic interface reads as shrinking.'],
    { appliesTo: ['progress', 'slider', 'rating', 'stepper', 'pagination', 'carousel'], checks: ['In RTL a progress bar at 25% has its filled part adjacent to the right edge.', 'In RTL the slider minimum is at the right, and page 1 of a pagination control is the rightmost page.', 'In RTL swiping toward the right shows the next slide of a carousel.', 'The digits of every label are in logical order (no reversed numerals).'], references: [ref('appleRtl', 'Controls: flip controls that show progress; Numbers and characters'), ref('materialBidi', 'Mirroring layout')], related: ['R-LAYOUT-006', 'R-LAYOUT-005'] }),
  r('R-LAYOUT-005', 'layout', 'should',
    ['اتجاه الرسوم البيانية والخطوط الزمنية قرار صريح', 'The direction of charts and timelines is an explicit decision'],
    ['الرسم البياني والخط الزمني وشريط تشغيل الوسائط لا ترث الاتجاه بصمت. لكل منها إعداد معلن: شريط التشغيل وموجة الصوت يبقيان من اليسار إلى اليمين، والخط الزمني السردي (خطوات، سجل) يتبع اتجاه الواجهة، والمحور الزمني في الرسم البياني يُحدَّد لكل منتج ويُختبر مع قرّائه.', 'A chart, a timeline and a media scrubber do not silently inherit direction. Each has a declared setting: the scrubber and audio waveform stay left to right, a narrative timeline (steps, history) follows the interface direction, and the time axis of a data chart is decided per product and tested with its readers.'],
    ['الإرشادات المنشورة تتفق على أن تشغيل الوسائط لا يُعكس، ولا تتفق على المحاور البيانية؛ والقرّاء العرب يرون الاتجاهين في المطبوعات.', 'Published guidance agrees that media playback is not mirrored and does not agree on chart axes; Arabic readers meet both directions in print.'],
    { appliesTo: ['chart', 'timeline', 'media'], checks: ['Chart and timeline components require a direction option or document a fixed one; none reads only the inherited direction.', 'A media scrubber fills left to right in RTL and its elapsed time is at the left.', 'Axis tick labels use the numerals preference and are isolated.'], references: [ref('materialBidi', 'What not to mirror: media controls, timelines'), ref('appleRtl', 'Controls; Images')], related: ['R-LAYOUT-004'] }),
  r('R-LAYOUT-006', 'layout', 'must',
    ['مفاتيح الأسهم تتبع ما يُرى', 'Arrow keys follow what is seen'],
    ['في العناصر الأفقية (ألسنة، قوائم أفقية، شرائح، منزلقات، شبكة التقويم) يحرّك مفتاح السهم الأيسر التركيز أو القيمة بصريًا إلى اليسار: أي إلى العنصر التالي في RTL. Home وEnd يذهبان إلى أول عنصر وآخره منطقيًا.', 'In horizontal widgets (tabs, menubars, carousels, sliders, the calendar grid) the left arrow key moves focus or value visually to the left: that is, to the next item in RTL. Home and End go to the logically first and last item.'],
    ['المستخدم يضغط السهم نحو الجهة التي يريدها على الشاشة. ربط «يمين» بـ«التالي» في كل اتجاه يجعل لوحة المفاتيح تعاكس العرض.', 'A person presses the arrow toward the side they want on screen. Binding "right" to "next" in every direction makes the keyboard contradict the display.'],
    { appliesTo: ['roving-focus', 'tabs', 'menu', 'slider', 'calendar-grid', 'grid-navigation', 'tree-model'], checks: ['In RTL ArrowLeft on tab n focuses tab n+1 and ArrowRight focuses tab n−1.', 'In RTL ArrowLeft on a slider increases its value.', 'In RTL ArrowLeft in a calendar grid moves to the next day.', 'In a tree in RTL, ArrowLeft expands a closed node and ArrowRight collapses it.', 'Every keyboard test of a horizontal pattern has an RTL variant.'], references: [ref('apg', 'Keyboard interaction notes for tabs, slider, tree view, grid'), ref('appleRtl', 'Controls')], related: ['R-LAYOUT-004'] }),
  r('R-LAYOUT-007', 'layout', 'must',
    ['الحركة والتحويلات والظلال تعرف الاتجاه', 'Motion, transforms and shadows know the direction'],
    ['كل translateX وموضع بداية الانزلاق والتدرج اللوني الأفقي والظل المزاح أفقيًا يُضرب في معامل الاتجاه. الدرج الجانبي يدخل من جهة البداية، والانتقال إلى الصفحة التالية يتحرك نحو النهاية.', 'Every translateX, slide origin, horizontal gradient and horizontally offset shadow is multiplied by a direction factor. A side drawer enters from the start side, and a forward page transition moves toward the end.'],
    ['الخصائص المنطقية لا تغطي التحويلات والحركة، فتبقى الحركة بالاتجاه القديم بعد قلب التخطيط.', 'Logical properties do not cover transforms and animation, so motion keeps its old direction after the layout flips.'],
    { appliesTo: ['recipes', 'motion', 'drawer', 'toast', 'carousel'], checks: ['No transform with a non-zero horizontal translation appears in CSS without a direction variable or a paired [dir] rule.', 'In RTL a start-side drawer\'s first animation frame is beyond the right edge.', 'Horizontal gradients and offset shadows that indicate scroll or elevation direction are mirrored in RTL.'], references: [ref('cssLogical', '1 Introduction'), ref('materialBidi', 'Mirroring layout')], related: ['R-LAYOUT-001'] }),
  r('R-LAYOUT-008', 'layout', 'should',
    ['محاذاة الأعمدة بحسب نوع البيانات', 'Column alignment follows the data type'],
    ['في الجداول: النص يُحاذى إلى البداية، والمبالغ والأعداد إلى النهاية بأرقام ثابتة العرض حتى تتراصف الخانات، والمعرّفات والهواتف إلى البداية داخل عزل LTR. ترتيب الأعمدة يتبع اتجاه الواجهة.', 'In tables: text is start-aligned, amounts and counts end-aligned with tabular figures so that places line up, identifiers and phones start-aligned inside an LTR isolate. Column order follows the interface direction.'],
    ['مقارنة المبالغ تتطلب تراصف الفاصلة العشرية، وهو لا يتحقق بأرقام متناسبة العرض.', 'Comparing amounts requires aligned decimal marks, which proportional figures do not give.'],
    { appliesTo: ['table'], checks: ['Money and number cells have text-align: end and font-variant-numeric: tabular-nums.', 'In RTL the first column in DOM order is the rightmost.', 'Identifier and phone cells isolate with direction ltr and text-align: start.'], references: [ref('cssFonts', '6.7 font-variant-numeric'), ref('appleRtl', 'Text alignment')], fixtures: ['table-harvested'], related: ['R-BIDI-008', 'R-LAYOUT-009'] }),
  r('R-LAYOUT-009', 'layout', 'must',
    ['المحاذاة إلى البداية، والفقرة الطويلة بحسب لغتها', 'Align to the start; a long paragraph by its own language'],
    ['نص الواجهة يُحاذى إلى start. عناصر القائمة الواحدة تتحاذى كلها إلى حافة واحدة ولو كان بعضها بلغة أخرى. الفقرة الطويلة (ثلاثة أسطر فأكثر) بلغة معاكسة للاتجاه تُحاذى بحسب لغتها.', 'Interface text is aligned to start. The items of one list all align to the same edge even when some are in another script. A long paragraph (three lines or more) in the opposite-direction language is aligned according to its own language.'],
    ['قائمة تتبدل حافتها من عنصر إلى آخر صعبة المسح؛ وفقرة لاتينية محاذاة إلى اليمين تُخفي بدايات أسطرها.', 'A list whose edge changes from item to item is hard to scan; a Latin paragraph aligned right hides the beginnings of its lines.'],
    { appliesTo: ['text', 'list', 'table'], checks: ['No component style uses text-align: left or right.', 'In an RTL list containing "Sara Haddad" between Arabic names, every item\'s text box starts at the same inline-start edge (the owner\'s mixedAlign "ui" default).', 'A block with dir="ltr" and three or more lines inside an RTL page has text-align: start resolved to left.'], references: [ref('appleRtl', 'Text alignment'), ref('cssText3', '7.1 text-align')], fixtures: ['names'], related: ['R-BIDI-005'] }),
  r('R-LAYOUT-010', 'layout', 'must',
    ['مواضع العناصر العائمة منطقية', 'Overlay placement is logical'],
    ['القوائم المنسدلة والتلميحات والنوافذ المنبثقة تُحدَّد مواضعها بقيم منطقية (start، end) تُحوَّل إلى جهات فيزيائية بحسب اتجاه العنصر المرجعي. والعنصر المنقول خارج الشجرة (portal) يحمل اتجاه ولغة وأرقام السياق الذي فتحه.', 'Menus, tooltips and popovers are placed with logical values (start, end) resolved to physical sides by the direction of the anchor. An element portaled out of the tree carries the direction, language and numerals of the scope that opened it.'],
    ['العنصر المنقول إلى نهاية المستند يفقد سياق والده، فيظهر بقالب LTR أو بأرقام مختلفة عن الصفحة.', 'An element moved to the end of the document loses its parent\'s context and appears LTR or with numerals different from the page.'],
    { appliesTo: ['anchored-position', 'overlay-layers', 'menu', 'tooltip', 'dialog', 'toast'], checks: ['Placement options are named with start/end; in RTL "bottom-start" aligns the overlay\'s right edge with the anchor\'s right edge.', 'Every portaled root element has the same dir, lang and data-numerals as the scope of its trigger.', 'A submenu in RTL opens to the left of its parent item.'], references: [ref('cssLogical'), ref('structuralBidi', 'Inheritance of direction')], related: ['R-LAYOUT-001', 'R-A11Y-003'] }),

  // ------------------------------------------------------------------ input
  r('R-INPUT-001', 'input', 'must',
    ['المؤشر والتحديد من المنصة لا من رسمنا', 'Caret and selection come from the platform, not from our drawing'],
    ['في الحقول النصية اترك حركة المؤشر والتحديد والحذف للمتصفح. لا ترسم مؤشرًا أو تحديدًا مخصصًا، ولا تحسب المواضع بعدد المحارف. أي معالجة للقيمة أثناء الكتابة تحفظ موضع المؤشر بوحدات العناقيد.', 'In text fields leave caret movement, selection and deletion to the browser. Do not draw a custom caret or selection and do not compute positions by counting characters. Any processing of the value while typing preserves the caret position in grapheme-cluster units.'],
    ['في النص المختلط التحديد المنطقي المتصل يظهر بصريًا قطعتين، والمؤشر له موضعان عند حد الاتجاه. والحذف الخلفي في العربية يزيل آخر علامة تشكيل أولًا. إعادة تنفيذ ذلك تنتج أخطاء لا تُحصى.', 'In mixed text a contiguous logical selection is visually two pieces, and the caret has two positions at a direction boundary. Backspace in Arabic removes the last mark first. Re-implementing this yields endless errors.'],
    { appliesTo: ['text-input', 'numeric-input', 'segmented-input'], checks: ['No field component renders its own caret or selection element.', 'After an input transformation (digit conversion, space replacement) the caret is after the same grapheme as before; verified by typing in the middle of each text-stress and amounts string.', 'Deleting from the end of text-stress TS-050 with Backspace removes one code point per press until the base letter (platform behaviour is not intercepted).', 'Selection APIs are called with UTF-16 offsets that lie on grapheme boundaries.'], references: [ref('alreq', '5.2 Grapheme/word segmentation & selection'), ref('msBidi', 'Implications for caret movement'), ref('uax9', '3.4 Reordering Resolved Levels')], fixtures: ['text-stress', 'mixed-direction'], related: ['R-BIDI-003'] }),
  r('R-INPUT-002', 'input', 'must',
    ['اللصق يُنظَّف بحسب نوع الحقل ولا يُسقط حروفًا', 'Paste is cleaned according to the field type and never drops letters'],
    ['عند اللصق: في الحقول المنظمة تُزال محارف التحكم بالاتجاه والمسافات المحيطة وتُحوَّل الأرقام ثم يُتحقق من الباقي كما هو؛ في النص الحر يُحفظ ما لُصق كاملًا. لا يُقتطع النص الملصوق بصمت عند حد الطول.', 'On paste: in structured fields bidi controls and surrounding whitespace are removed, digits are converted, and the rest is validated as it stands; in free text what was pasted is kept whole. Pasted text is never silently cut at a length limit.'],
    ['أغلب الأرقام والرموز تُدخل لصقًا، ومعها ما لا يُرى. والاقتطاع الصامت يحفظ رقم حساب ناقصًا يبدو سليمًا.', 'Most numbers and codes are entered by paste, along with what cannot be seen. Silent truncation stores an incomplete account number that looks fine.'],
    { appliesTo: ['text-input', 'numeric-input', 'phone-input', 'segmented-input'], checks: ['Pasting amounts AM-070…AM-074 gives the expected value; pasting phone-inputs PI-013…PI-015 gives the expected E.164.', 'Pasting a string longer than maxlength shows an error or the full text marked invalid; the field value is never a silent prefix.', 'Pasting a full code into the first cell of a segmented input distributes it across the cells.', 'Pasting into a free-text field leaves the code points unchanged.'], references: [ref('uax9', '2 Directional Formatting Characters'), ref('html', '4.10.5.3.1 maxlength')], fixtures: ['amounts', 'phone-inputs', 'text-stress'], related: ['R-BIDI-006', 'R-NUM-006'] }),
  r('R-INPUT-003', 'input', 'must',
    ['لوحة المفاتيح المناسبة عبر inputmode لا type=number', 'The right keyboard via inputmode, not type=number'],
    ['الحقول الرقمية تستخدم type="text" مع inputmode المناسب (numeric للأعداد الصحيحة والرموز، decimal للمبالغ، tel للهواتف) وautocomplete الملائم. لا تستخدم type="number".', 'Numeric fields use type="text" with the appropriate inputmode (numeric for integers and codes, decimal for amounts, tel for phones) and a fitting autocomplete. Do not use type="number".'],
    ['type=number يرفض الأرقام العربية المشرقية والفاصلة «٫» في معظم المتصفحات ويعيد قيمة فارغة دون تفسير، ويغيّر القيمة بعجلة الفأرة، ويحذف الأصفار البادئة. ولوحة الأرقام على الهاتف قد تُظهر أرقامًا مشرقية بحسب إعدادات الجهاز فيجب قبولها.', 'type=number rejects Arabic-Indic digits and the "٫" separator in most browsers and returns an empty value with no explanation, changes the value on mouse wheel and drops leading zeros. A phone\'s numeric keypad may produce Arabic-Indic digits depending on device settings, so they must be accepted.'],
    { appliesTo: ['numeric-input', 'currency-input', 'phone-input', 'segmented-input'], checks: ['No component renders input[type=number].', 'Amount fields have inputmode="decimal"; integer, OTP and card fields inputmode="numeric"; phone fields inputmode="tel".', 'One-time-code fields have autocomplete="one-time-code".', 'Typing ١٢٣ in every numeric field is accepted (R-NUM-001).'], references: [ref('html', '6.8.7 Input modalities: the inputmode attribute; 4.10.5.1.12 Number state'), ref('wcag', '1.3.5 Identify Input Purpose')], fixtures: ['amounts'], related: ['R-NUM-001', 'R-PHONE-003'] }),
  r('R-INPUT-004', 'input', 'must',
    ['اتجاه الحقل من نوع بياناته', 'A field\'s direction comes from its data type'],
    ['لكل حقل اتجاه محتوى معلن: النص الحر auto (يتبع ما يُكتب)، والأرقام والهواتف والبريد والروابط والرموز ltr، والنص العربي المعروف rtl. النص التوضيحي داخل الحقل (placeholder) يتبع لغة الواجهة.', 'Every field has a declared content direction: free text auto (follows what is typed), numbers, phones, e-mail, URLs and codes ltr, known-Arabic text rtl. The placeholder follows the interface language.'],
    ['حقل نص حر ثابت على RTL يعرض اسمًا لاتينيًا بعلامات ترقيمه في الجهة الخطأ، وحقل مبلغ RTL يُظهر السالب بعد الرقم.', 'A free-text field fixed to RTL shows a Latin name with its punctuation on the wrong side, and an RTL amount field shows the minus after the number.'],
    { appliesTo: ['text-field', 'text-input', 'numeric-input'], checks: ['Free-text inputs and textareas have dir="auto"; numeric, phone, e-mail, URL and code inputs have computed direction ltr.', 'An empty dir="auto" field in an RTL page shows its placeholder right-aligned in Arabic.', 'The field\'s start-aligned adornments (icon, prefix) stay at the interface start whatever the content direction.'], references: [ref('html', '3.2.6.4 The dir attribute (auto)'), ref('structuralBidi', 'Form fields'), ref('inlineBidi')], fixtures: ['names', 'mixed-direction'], related: ['R-BIDI-009', 'R-BIDI-005'] }),
  r('R-INPUT-005', 'input', 'should',
    ['نبّه إلى الكتابة بتخطيط خاطئ ولا تحوّلها آليًا', 'Flag wrong-layout typing; do not convert it automatically'],
    ['حين يبدو المدخل مكتوبًا بتخطيط لوحة مفاتيح غير المقصود (حروف لاتينية بلا معنى تقابل كلمة عربية على المفاتيح نفسها، أو العكس) اعرض اقتراحًا بالتحويل يقبله المستخدم. في حقول كلمة المرور اعرض تخطيط الكتابة الحالي إن أمكن.', 'When input appears typed in the wrong keyboard layout (meaningless Latin letters that map to an Arabic word on the same keys, or the reverse) offer a conversion the person can accept. In password fields show the active layout when it can be known.'],
    ['مستخدمو العربية يبدّلون التخطيط باستمرار، و«hglsjo]l» بدل «المستخدم» خطأ يومي. لكن التحويل الآلي يفسد أسماء وكلمات صحيحة.', 'Arabic users switch layouts constantly, and "hglsjo]l" for «المستخدم» is an everyday mistake. But automatic conversion corrupts valid names and words.'],
    { appliesTo: ['search-field', 'text-field', 'combobox'], checks: ['A search with zero results whose query maps, key for key, to a string in the other layout that has results shows a suggestion; the query is not replaced without action.', 'The mapping table used names the layouts it covers (e.g. Arabic 101 ↔ US QWERTY).', 'No field rewrites typed letters into another script.'], references: [ref('msBidi'), ref('alreq', '5.1 Characters & encoding')], related: ['R-SRCH-005'] }),
  r('R-INPUT-006', 'input', 'must',
    ['احترم التركيب والتصحيح الآلي', 'Respect composition and autocorrect'],
    ['لا تعالج القيمة ولا تتحقق منها أثناء جلسة تركيب (بين compositionstart وcompositionend). عطّل التصحيح الآلي والتكبير الآلي والتدقيق الإملائي في حقول الأسماء والرموز والبريد، واضبط lang على الحقل ليختار النظام لوحة المفاتيح والقاموس.', 'Do not process or validate the value during a composition session (between compositionstart and compositionend). Turn off autocorrect, autocapitalise and spellcheck in name, code and e-mail fields, and set lang on the field so the system chooses the keyboard and dictionary.'],
    ['لوحات المفاتيح على الهواتف والإملاء الصوتي وبعض التخطيطات تُدخل النص تركيبًا؛ تعديل القيمة في منتصفه يكرر الحروف أو يُسقطها. والتصحيح الآلي يغيّر الأسماء العربية إلى كلمات شائعة.', 'Phone keyboards, dictation and some layouts enter text by composition; changing the value midway duplicates or drops letters. Autocorrect changes Arabic names into common words.'],
    { appliesTo: ['text-input', 'numeric-input', 'combobox', 'typeahead'], checks: ['Input handlers return early while event.isComposing is true and run once at compositionend.', 'Name, code and e-mail inputs have autocorrect="off", autocapitalize="none" and spellcheck="false".', 'Typing a name with a mobile Arabic keyboard in a combobox does not duplicate characters (automated with composition events).'], references: [ref('html', '6.8.6 autocapitalize; 6.8.8 spellcheck'), ref('wcag', '3.1.2 Language of Parts')], fixtures: ['names'], related: ['R-INPUT-001'] }),
  r('R-INPUT-007', 'input', 'must',
    ['الحقول المقطّعة تسلسل LTR يقبل أي أرقام', 'Segmented fields are an LTR sequence that accepts any digits'],
    ['خانات رمز التحقق ورقم البطاقة وتاريخ الانتهاء وأجزاء الوقت تُرتَّب من اليسار إلى اليمين في كل اتجاه، وتقبل الأرقام بأي نظام وتعرضها بنظام التفضيل، وينتقل التركيز بين الخانات بترتيب الكتابة.', 'The cells of a verification code, card number, expiry date and time parts are ordered left to right in every direction, accept digits of any system and display them in the preferred one, and focus moves between cells in typing order.'],
    ['الرمز المرسل «482913» يُقرأ ويُكتب من اليسار. خانات مرتبة من اليمين تجعل أول رقم يُكتب في آخر موضع يُقرأ.', 'The code "482913" sent to the person is read and typed from the left. Cells ordered from the right put the first typed digit in the last position read.'],
    { appliesTo: ['segmented-input', 'date-field', 'time'], checks: ['In RTL the first cell of an OTP or card field is the leftmost and receives the first typed digit.', 'Typing ٤٨٢٩١٣ fills six cells and the submitted value is "482913".', 'Date segments follow the locale\'s field order but each segment\'s digits are in logical order.', 'ArrowLeft/ArrowRight move between cells visually.'], references: [ref('appleRtl', 'Numbers and characters: never reverse the digits of a number'), ref('html', 'autocomplete one-time-code, cc-number')], fixtures: ['amounts'], related: ['R-NUM-001', 'R-BIDI-008'] }),
  r('R-INPUT-008', 'input', 'should',
    ['اختصارات لوحة المفاتيح تعمل مع التخطيط العربي', 'Keyboard shortcuts work under the Arabic layout'],
    ['الاختصارات تُطابَق بالمفتاح الفيزيائي (event.code) أو بالحرف في كلا التخطيطين، وتُعرض للمستخدم بالرمز المطبوع على المفتاح. لا تستخدم اختصارًا بحرف واحد دون مفتاح تعديل.', 'Shortcuts are matched by physical key (event.code) or by the character in both layouts, and shown to the person with the legend printed on the key. Do not use single-letter shortcuts without a modifier.'],
    ['مع التخطيط العربي يعطي Ctrl+S الحرف «س» في event.key في بعض المتصفحات فلا يعمل الاختصار. والاختصار بحرف واحد يتعارض مع الكتابة وأوامر الصوت.', 'Under the Arabic layout Ctrl+S reports «س» in event.key in some browsers, so the shortcut fails. A single-letter shortcut conflicts with typing and speech commands.'],
    { appliesTo: ['shortcuts', 'menu'], checks: ['Each registered shortcut fires when dispatched with the Arabic-layout key value and the same code.', 'No shortcut consists of a single printable character without Ctrl, Alt or Meta, or it can be turned off.', 'Shortcut hints are isolated LTR.'], references: [ref('wcag', '2.1.4 Character Key Shortcuts'), ref('apg', 'Developing a Keyboard Interface')], related: ['R-LAYOUT-006'] }),

  // ------------------------------------------------------------------ content
  r('R-CNT-002', 'content', 'should',
    ['صياغة لا تفترض جنس المخاطَب', 'Wording that does not assume the reader\'s gender'],
    ['اكتب نص الواجهة بصيغ لا تتغير بتغير جنس المخاطب: المصدر («تسجيل الدخول»)، أو الجمل الاسمية، أو المبني للمجهول. تجنب صيغة «أدخل/أدخلي» المزدوجة والشرطة المائلة.', 'Write interface text in forms that do not change with the reader\'s gender: the verbal noun («تسجيل الدخول»), nominal sentences, or the passive. Avoid doubled forms such as «أدخل/أدخلي» and slashes.'],
    ['الأمر والمضارع والصفات في العربية تتصرف بحسب الجنس. صيغة المذكر وحدها تُقصي نصف المستخدمين، والمزدوجة تثقل القراءة وقارئ الشاشة.', 'Imperatives, present verbs and adjectives in Arabic inflect for gender. Masculine-only wording excludes half the users, and doubled forms burden reading and screen readers.'],
    { appliesTo: ['messages'], checks: ['No message contains a slash between two inflected forms of one word (pattern: Arabic word, "/", Arabic word sharing its first three letters).', 'Messages that address the reader with a gendered adjective or second-person verb are listed for review; the list is empty or each entry has a recorded justification.', 'Where the product knows the reader\'s gender, messages select by it through the message format, not by concatenation.'], references: [ref('cldr', 'grammatical gender features (ar)')], related: ['R-CNT-003', 'R-CNT-005'] }),
  r('R-CNT-003', 'content', 'should',
    ['تسميات الأزرار مصادر بصيغة واحدة', 'Button labels are verbal nouns, in one consistent form'],
    ['سمِّ الأفعال في الأزرار والقوائم بالمصدر («حفظ»، «إلغاء»، «إضافة عميل») في كل النظام. لا تخلط المصدر بفعل الأمر في واجهة واحدة، ولا تُنهِ التسمية بنقطة.', 'Name actions on buttons and menus with the verbal noun («حفظ», «إلغاء», «إضافة عميل») throughout the system. Do not mix verbal nouns and imperatives in one interface, and do not end a label with a full stop.'],
    ['المصدر محايد الجنس وقصير وهو الشائع في الأنظمة العربية. الخلط بين «احفظ» و«حفظ» يوحي بأنهما فعلان مختلفان.', 'The verbal noun is gender-neutral, short and the prevailing convention in Arabic systems. Mixing «احفظ» and «حفظ» suggests two different actions.'],
    { appliesTo: ['messages', 'button', 'menu'], checks: ['Every default label shipped with components for an action is in the glossary of action names, in verbal-noun form.', 'No button or menu-item label ends with "." or "؟".', 'The glossary has exactly one Arabic term per action key.'], references: [ref('materialBidi')], related: ['R-CNT-002'] }),
  r('R-CNT-004', 'content', 'must',
    ['ست صيغ للجمع', 'Six plural forms'],
    ['كل رسالة فيها عدد تُكتب بالصيغ الست التي تعرّفها CLDR للعربية (zero، one، two، few، many، other) وتُختار الصيغة بالقاعدة، لا بشرط «إذا كان العدد واحدًا».', 'Every message containing a count is written in the six forms CLDR defines for Arabic (zero, one, two, few, many, other) and the form is selected by the rule, not by an "if the count is one" condition.'],
    ['المعدود في العربية يتغير: مفرد، مثنى، جمع للأعداد 3–10، مفرد منصوب للأعداد 11–99، مفرد مجرور للمئة والألف. «3 ملف» و«11 ملفات» خطآن يراهما كل قارئ. ومكتبات شائعة تقدم للعربية صيغتين فقط.', 'The counted noun changes in Arabic: singular, dual, plural for 3–10, accusative singular for 11–99, genitive singular for hundreds and thousands. «3 ملف» and «11 ملفات» are errors every reader sees. Common libraries ship only two forms for Arabic.'],
    { appliesTo: ['messages', 'plural-select'], checks: ['plural-agreement: the selected category equals expected.category for all 102 cases.', 'Every Arabic plural message defines all six categories (or declares which are impossible for its range).', 'Component-internal strings with counts (selected items, results, pages, characters remaining) pass the same test.', 'For counts 0, 1 and 2 the phrase contains no digit when the form expresses the number in words.'], references: [ref('cldr', 'supplemental plurals (ar)')], fixtures: ['plural-agreement'], related: ['R-CNT-005'] }),
  r('R-CNT-005', 'content', 'must',
    ['لا تُركَّب الجمل من قطع', 'Sentences are not assembled from pieces'],
    ['الرسالة جملة كاملة فيها مواضع للمتغيرات. لا تضم كلمات أو أجزاء جمل برمجيًا، ولا تُلحق «ال» أو لاحقة بمتغير، ولا تفترض ترتيب الكلمات. المتغيرات النصية تُعزل اتجاهيًا، والأعداد والتواريخ تدخل منسَّقة.', 'A message is a whole sentence with placeholders. Do not join words or sentence fragments in code, do not attach «ال» or a suffix to a variable, and do not assume word order. Text variables are bidi-isolated; numbers and dates go in formatted.'],
    ['العربية تطابق العدد والمعدود والصفة والفعل في الجنس والعدد والإعراب، والترتيب يختلف عن الإنجليزية. القطع المركبة صحيحة في لغة واحدة فقط.', 'Arabic agrees number, counted noun, adjective and verb in gender, number and case, and its word order differs from English. Assembled fragments are correct in one language only.'],
    { appliesTo: ['messages'], checks: ['No source file concatenates a translated string with another string or variable to form displayed text (lint: string concatenation or template literal around a message call).', 'Every placeholder that receives user text is rendered through an isolating element or FSI…PDI.', 'No message value starts or ends with a space.'], references: [ref('inlineBidi', 'Text inserted into a template'), ref('cldr', 'MessageFormat plural and select')], fixtures: ['plural-agreement', 'mixed-direction'], related: ['R-CNT-004', 'R-BIDI-005'] }),
  r('R-CNT-006', 'content', 'must',
    ['الاسم يُعرض ويُخزَّن كما كتبه صاحبه', 'A name is shown and stored as its owner wrote it'],
    ['لا تقسّم الاسم العربي آليًا إلى «أول» و«أخير»، ولا تصحح همزاته أو تحذف تشكيله أو تطبّع مسافاته في القيمة المخزنة. الحرف الأول للصورة الرمزية هو أول عنقود كتابي بشكله المنفرد، وتُتخطى ألقاب مثل «د.» و«م.» عند توفر قائمة بها.', 'Do not split an Arabic name automatically into "first" and "last", and do not correct its hamzas, remove its diacritics or normalise its spaces in the stored value. The avatar initial is the first grapheme cluster in its isolated shape, and honorifics such as «د.» and «م.» are skipped when a list of them is available.'],
    ['الأسماء المركبة («عبد الله»، «أبو بكر») والأنساب («بن»، «آل») لا تُشطر عند أول مسافة. والاسم ملك صاحبه. والحرف الأول من «عبد الله» إن رُسم متصلًا بما بعده يظهر مبتورًا.', 'Compound names («عبد الله», «أبو بكر») and lineage particles («بن», «آل») cannot be cut at the first space. A name belongs to its owner. And the first letter of «عبد الله», if drawn as though joined to the next, looks cut off.'],
    { appliesTo: ['text-field', 'avatar', 'form'], checks: ['For every names case the stored value equals input.text code point for code point (only leading and trailing whitespace may be trimmed, by an explicit rule).', 'No form requires separate first-name and last-name fields without a single full-name alternative.', 'The avatar initial of each names case is one grapheme cluster and renders in its isolated form.', 'Sorting names uses locale collation and does not strip «ال» unless the product states it.'], references: [ref('alreq', '4.3.1 Joining Forms'), ref('wcag', '3.3.2 Labels or Instructions')], fixtures: ['names'], related: ['R-SRCH-001', 'R-SRCH-002'] }),
  r('R-CNT-007', 'content', 'should',
    ['ترقيم عربي في النص العربي', 'Arabic punctuation in Arabic text'],
    ['النص العربي يستخدم الفاصلة «،» والفاصلة المنقوطة «؛» وعلامة الاستفهام «؟» وعلامتي التنصيص «…»، ولا يستخدم نظائرها اللاتينية. علامة الحذف محرف واحد (…) لا ثلاث نقاط.', 'Arabic text uses the Arabic comma «،», semicolon «؛», question mark «؟» and guillemets «…», not their Latin counterparts. The ellipsis is one character (…), not three dots.'],
    ['العلامات اللاتينية داخل نص عربي تبدو مقلوبة الاتجاه (الفاصلة والاستفهام)، وعلامات التنصيص المستقيمة تتشابه مع رموز البوصة والثواني في البيانات.', 'Latin marks inside Arabic text look turned the wrong way (comma, question mark), and straight quotes are confused with inch and seconds signs in data.'],
    { appliesTo: ['messages'], checks: ['No Arabic message contains U+002C, U+003B or U+003F adjacent to an Arabic letter.', 'No Arabic message contains three consecutive U+002E.', 'Quoted interface terms in Arabic messages use U+00AB and U+00BB.'], references: [ref('alreq', '6 Punctuation & inline features; A.4 Punctuation and symbols')], related: ['R-BIDI-007'] }),

  // ------------------------------------------------------------------ flow
  r('R-FLOW-002', 'flow', 'must',
    ['العملية المالية تحمل مفتاح عدم تكرار', 'A financial operation carries an idempotency key'],
    ['كل إرسال ينشئ أثرًا ماليًا أو لا رجعة فيه يحمل معرّفًا فريدًا يُنشأ عند فتح النموذج ويُعاد استعماله عند إعادة المحاولة، حتى لا تُنفَّذ العملية مرتين إذا انقطع الاتصال بعد الإرسال.', 'Every submission that creates a financial or irreversible effect carries a unique identifier created when the form opens and reused on retry, so the operation is not executed twice if the connection drops after sending.'],
    ['حراسة الزر تمنع الضغط المزدوج، لكنها لا تمنع إعادة المحاولة بعد مهلة انتهت والطلب الأول قد نُفّذ.', 'Guarding the button prevents a double press, but not a retry after a timeout when the first request did succeed.'],
    { appliesTo: ['form', 'button'], checks: ['Two submissions of the same form instance (submit, simulated timeout, retry) send the same idempotency key.', 'A new form instance sends a different key.', 'The retry action after a failure reuses the preserved input (R-CNT-001).'], references: [ref('wcag', '3.3.4 Error Prevention (Legal, Financial, Data)')], related: ['R-FLOW-001', 'R-CNT-001'] }),
  r('R-FLOW-003', 'flow', 'should',
    ['التأكيد يعيد عرض القيمة كما ستُسجَّل', 'Confirmation restates the value as it will be recorded'],
    ['قبل تنفيذ عملية مالية اعرض ملخصًا يعيد المبلغ بأرقام التفضيل وبعملته، واسم الطرف الآخر كما هو مخزَّن، وما سيحدث. زر التأكيد يسمّي الفعل («تأكيد التحصيل») لا «موافق».', 'Before executing a financial operation show a summary that restates the amount in the preferred numerals with its currency, the other party\'s name as stored, and what will happen. The confirm button names the action («تأكيد التحصيل»), not "OK".'],
    ['ما كُتب في الحقل قد يختلف عما فُهم (فاصلة، نظام أرقام). إعادة العرض بالصيغة المنسَّقة فرصة أخيرة لاكتشاف الخطأ.', 'What was typed may differ from what was understood (a comma, a numeral system). Restating it in formatted form is the last chance to catch the error.'],
    { appliesTo: ['dialog', 'form'], checks: ['The confirmation step renders the amount through the money formatter (grouped, with currency), not the raw input string.', 'The confirm button\'s accessible name contains the action\'s glossary term.', 'The summary is reachable by a screen reader before the confirm button in reading order.'], references: [ref('wcag', '3.3.4 Error Prevention (Legal, Financial, Data)')], related: ['R-FLOW-001', 'R-NUM-004'] }),

  // ------------------------------------------------------------------ accessibility
  r('R-A11Y-003', 'accessibility', 'must',
    ['اللغة والاتجاه معلنان على الجذر وعلى كل نطاق مختلف', 'Language and direction are declared on the root and on every scope that differs'],
    ['العنصر الجذر يحمل lang وdir. كل مقطع بلغة أخرى (كلمة إنجليزية، اسم لاتيني، اقتباس) يحمل lang الخاص به، ومعه dir إن اختلف الاتجاه. الاتجاه لا يُستنتج من اللغة ولا العكس.', 'The root element carries lang and dir. Every passage in another language (an English word, a Latin name, a quotation) carries its own lang, and dir too if the direction differs. Direction is not inferred from language, nor the reverse.'],
    ['قارئ الشاشة يختار صوت النطق من lang؛ دونها تُقرأ الإنجليزية بصوت عربي حرفًا حرفًا أو تُتخطى. والمتصفح يختار الخط وقواعد الكسر والتدقيق من اللغة.', 'A screen reader chooses its voice from lang; without it English is spelled out by an Arabic voice or skipped. The browser chooses font, line-breaking and spellchecking from the language.'],
    { appliesTo: ['locale-provider', 'text', 'layout'], checks: ['The html element has a valid BCP 47 lang and a dir attribute.', 'Every locale scope element sets lang and dir together.', 'Runs of four or more Latin letters forming words inside lang="ar" content are wrapped in an element with a non-Arabic lang, or listed as proper names exempt under 3.1.2.', 'Portaled content carries the lang and dir of its trigger scope.'], references: [ref('wcag', '3.1.1 Language of Page; 3.1.2 Language of Parts'), ref('langDecl'), ref('structuralBidi')], related: ['R-BIDI-013', 'R-LAYOUT-010'] }),
  r('R-A11Y-004', 'accessibility', 'must',
    ['ترتيب المصدر هو ترتيب القراءة', 'Source order is reading order'],
    ['ترتيب العناصر في DOM هو الترتيب المنطقي للقراءة في الاتجاهين. لا تُنشئ مظهر RTL بعكس ترتيب العناصر (row-reverse، order، float) ولا بكتابة النص معكوسًا أو بترتيب بصري.', 'The order of elements in the DOM is the logical reading order in both directions. Do not create an RTL appearance by reversing element order (row-reverse, order, float) or by writing text reversed or in visual order.'],
    ['قارئ الشاشة ومفتاح Tab يتبعان المصدر. التخطيط المعكوس بصريًا يجعل التنقل يسير من النهاية إلى البداية.', 'Screen readers and the Tab key follow the source. A visually reversed layout makes navigation run from the end to the start.'],
    { appliesTo: ['layout', 'recipes'], checks: ['The sequence of focusable elements in DOM order equals their visual order along the inline axis from start to end, in both directions.', 'No style uses flex-direction: row-reverse or order to produce the RTL layout.', 'No text node contains Arabic stored in visual order (presentation forms U+FE70–U+FEFF outside test data).'], references: [ref('wcag', '1.3.2 Meaningful Sequence; 2.4.3 Focus Order'), ref('ubaBasics', 'Logical order')], fixtures: ['text-stress'], related: ['R-LAYOUT-001'] }),
  r('R-A11Y-005', 'accessibility', 'should',
    ['اختبر نطق الأرقام والنص المختلط', 'Test how numbers and mixed text are spoken'],
    ['القيم المنسَّقة للعرض (هاتف مجمَّع، مبلغ بفواصل، تاريخ رقمي، معرّف) تُختبر مع قارئ شاشة عربي. حيث يُنطق التنسيق خطأ يُقدَّم نص بديل مسموع: الهاتف رقمًا رقمًا، والمبلغ بقيمته وعملته، والتاريخ باسم الشهر.', 'Values formatted for display (a grouped phone number, an amount with separators, a numeric date, an identifier) are tested with an Arabic screen reader. Where the formatting is spoken wrongly an audible alternative is supplied: the phone digit by digit, the amount with its value and currency, the date with the month name.'],
    ['المحركات الصوتية تقرأ «010 1234 5678» ثلاثة أعداد، و«١٬٢٣٤٫٥٠» قد تُقرأ عددين، والمسافات غير القاطعة والمحارف الخفية قد تُنطق أو تقطع الكلام. النتيجة تختلف بين القارئات، فلا بد من اختبار مسجَّل.', 'Speech engines read "010 1234 5678" as three numbers, «١٬٢٣٤٫٥٠» may be read as two, and no-break spaces or invisible characters may be spoken or interrupt speech. Results differ between readers, so a recorded test is needed.'],
    { appliesTo: ['phone-format', 'money-format', 'date-format', 'text'], checks: ['Components that display a phone number, amount or numeric date accept and render an accessible text alternative distinct from the visual string.', 'The accessible name of no element contains a bidi control character.', 'A recorded screen-reader run exists for each of: phone, amount, date, identifier, mixed Arabic/Latin sentence — per supported reader.'], references: [ref('wcag', '1.3.1 Info and Relationships; 3.1.2 Language of Parts'), ref('apg', 'Providing Accessible Names and Descriptions')], fixtures: ['formatting-harvested', 'mixed-direction'], related: ['R-A11Y-003', 'R-BIDI-011'] }),
  r('R-A11Y-006', 'accessibility', 'must',
    ['التكبير حتى 200٪ دون قص للنص العربي', 'Zoom to 200% without clipping Arabic text'],
    ['عند تكبير النص إلى 200٪ أو تضييق العرض إلى 320 بكسل يبقى كل نص عربي مقروءًا كاملًا بعلاماته، دون تمرير أفقي، ومساحات اللمس لا تتراكب.', 'With text enlarged to 200% or the viewport narrowed to 320 px, all Arabic text stays fully readable with its marks, with no horizontal scrolling, and touch targets do not overlap.'],
    ['النص العربي أعلى من اللاتيني وأقصر عرضًا في بعض الخطوط وأطول في أخرى؛ التخطيطات المضبوطة على الإنجليزية تنكسر عند التكبير.', 'Arabic text is taller than Latin and narrower in some fonts, wider in others; layouts tuned for English break when enlarged.'],
    { appliesTo: ['layout', 'text', 'button', 'table'], checks: ['At 200% text size no element containing Arabic text has clipped ink (scroll size equals client size, or overflow is visible).', 'At 320 CSS px width the page has no horizontal scroll with long-Arabic content (text-stress TS-001).', 'Font sizes and line heights are in relative units.'], references: [ref('wcag', '1.4.4 Resize Text; 1.4.10 Reflow; 2.5.8 Target Size (Minimum)')], fixtures: ['text-stress'], related: ['R-TYPE-002', 'R-TYPE-007'] }),
  r('R-A11Y-007', 'accessibility', 'must',
    ['الأسماء المسموعة تصف الفعل لا الشكل ولا الجهة', 'Accessible names describe the action, not the shape or the side'],
    ['الاسم المتاح للزر والأيقونة يصف ما يفعله بالعربية («التالي»، «الرجوع»، «إغلاق») ولا يذكر شكلًا أو جهة («سهم إلى اليسار»). وحالة العنصر (موسَّع، محدد، مشغول) تُعلن بخصائص ARIA لا بنص مرئي فقط.', 'The accessible name of a button or icon describes what it does, in Arabic («التالي», «الرجوع», «إغلاق»), and mentions no shape or side ("left arrow"). The element\'s state (expanded, selected, busy) is announced through ARIA properties, not only visible text.'],
    ['الأيقونة تنعكس مع الاتجاه فيصير وصف الجهة خاطئًا. ومن لا يرى الشاشة لا تعنيه الجهة.', 'The icon flips with direction, making a description of the side wrong. And the side means nothing to someone who cannot see the screen.'],
    { appliesTo: ['icon-button', 'button', 'menu', 'tabs'], checks: ['No default accessible name contains the Arabic or English words for left, right or arrow.', 'Every default accessible name shipped for lang=ar contains at least one Arabic letter.', 'Toggle, disclosure and busy states are exposed via aria-pressed, aria-expanded and aria-busy.'], references: [ref('wcag', '4.1.2 Name, Role, Value; 1.3.3 Sensory Characteristics'), ref('apg', 'Providing Accessible Names and Descriptions')], related: ['R-A11Y-001', 'R-ICON-003'] }),
]
